/* Named groups are private organization of owned gift instances, never grants. */
(() => {
 'use strict';
 let app=null,identity='',epoch=0,intent=0,mutation=null,catalog=new Map(),context={kind:'list',group:null,offset:0},pickerId=null,focusInstance='';
 const positions=new Map();
 const state=()=>app?.state||{},$=id=>document.getElementById(id),esc=value=>app.esc(value),encode=value=>encodeURIComponent(value);
 function reset(){identity='';epoch++;intent++;mutation=null;catalog.clear();context={kind:'list',group:null,offset:0};pickerId=null;focusInstance='';positions.clear();}
 function sync(){const id=state().account?.id||'';if(identity!==id){reset();identity=id;}}
 function guard(){sync();const id=identity,e=epoch,session=state().session?.id||'',parent=app.guard();return ()=>!!id&&identity===id&&epoch===e&&state().account?.id===id&&(state().session?.id||'')===session&&parent();}
 const art=id=>window.VoidCosmetics?.art?.(id)||'';
 const title=id=>catalog.get(id)?.name||'Owned gift';
 const edition=id=>window.VoidCosmetics?.editionLabel?.(catalog.get(id))||catalog.get(id)?.editionLabel||'';
 const errors='<p id="vgc-error" class="vgc-error" role="alert"></p>';
 function positionKey(){return context.kind+':'+(context.group?.id||pickerId||'')+':'+context.offset;}
 function rememberContext(){const panel=document.querySelector?.('.vgc-panel'),dialog=panel?.closest?.('dialog');if(dialog)positions.set(positionKey(),Number(dialog.scrollTop)||0);}
 function restoreContext(){const panel=document.querySelector?.('.vgc-panel'),dialog=panel?.closest?.('dialog');if(!dialog)return;const top=positions.get(positionKey())||0,id=focusInstance,current=guard(),ticket=state().dialogGeneration;const restore=()=>{if(!current()||ticket!==state().dialogGeneration)return;dialog.scrollTop=top;if(id){const button=[...panel.querySelectorAll?.('[data-vgc="inspect"]')||[]].find(node=>node.dataset.instance===id);button?.focus?.({preventScroll:true});}focusInstance='';};if(window.requestAnimationFrame)window.requestAnimationFrame(restore);else restore();}

 function show(title,copy,html){return app.showDialog(title,copy,`<section class="vgc-panel">${html}</section>`);}
 function statusError(error){const node=$('vgc-error');if(node){node.textContent=error.message||'The collection could not be updated. Please retry.';if(error.code==='collection_changed')node.insertAdjacentHTML?.('beforeend',' <button type="button" class="vh-text-button" data-vgc="reload">Reload latest collection</button>');}else app.announce(error.message||'The collection could not be updated.');}
 function verify(data){if(!data||data.accountId!==identity)throw Error('The collection response belongs to another account. Reload before trying again.');return data;}
 async function loadCatalog(current){if(catalog.size)return;const data=await app.request('/api/cosmetics/catalog');if(current())catalog=new Map((data.items||[]).map(item=>[item.id,item]));}
 async function load(path,kind,copy,paint){
  const current=guard();if(!identity)return;rememberContext();const request=++intent,ticket=show('Gift collections',copy,`<p role="status">Loading your private collections…</p>${errors}`);mutation=null;
  try{const [data]=await Promise.all([app.request('/api/gift-collections'+path),loadCatalog(current)]);if(!current()||request!==intent||ticket!==state().dialogGeneration)return;paint(verify(data));}
  catch(error){if(current()&&request===intent&&ticket===state().dialogGeneration){const node=$('vgc-error');if(node)node.textContent=error.message||'Your collections could not load.';}}
 }
 function collectionRow(group,instance){return `<article class="vgc-group"><div><button class="vgc-group-name" data-vgc="group" data-group="${esc(group.id)}">${esc(group.name)}</button><small>${Number(group.count)||0} ${(Number(group.count)||0)===1?'gift':'gifts'} · Private group</small></div><div class="vgc-actions">${instance?`<button type="button" class="${group.included?'vh-secondary':'vh-primary'}" data-vgc="toggle" data-group="${esc(group.id)}" data-instance="${esc(instance.id)}" data-revision="${Number(group.revision)}" data-included="${group.included?'false':'true'}" aria-pressed="${group.included}">${group.included?'Remove from group':'Add to group'}</button>`:''}<button class="vh-secondary" data-vgc="rename" data-group="${esc(group.id)}" data-name="${esc(group.name)}" data-revision="${Number(group.revision)}">Rename</button><button class="vh-text-button" data-vgc="delete" data-group="${esc(group.id)}" data-name="${esc(group.name)}" data-revision="${Number(group.revision)}">Remove group</button></div></article>`;}
 function listHTML(data){const instance=data.instance;context={kind:instance?'picker':'list',group:null,offset:0};pickerId=instance?.id||null;show(instance?'Add gift to collections':'Gift collections','Private groups organize the gifts you own. One gift can appear in several groups.',`${instance?`<div class="vgc-selected"><span class="vgc-art">${art(instance.catalogId)}</span><div><h3>${esc(title(instance.catalogId))}</h3><p>Owned instance · …${esc(instance.id.slice(-8))}</p></div></div>`:''}<div class="vgc-toolbar"><p>${data.collections.length} of ${Number(data.maxCollections)||24} groups</p><button class="vh-primary" data-vgc="create" ${data.collections.length>=(Number(data.maxCollections)||24)?'disabled':''}>Create collection</button></div>${errors}<div class="vgc-groups">${data.collections.length?data.collections.map(group=>collectionRow(group,instance)).join(''):'<div class="vgc-empty"><h3>No collections yet</h3><p>Create a private group, then add gifts from your inventory. No gifts are claimed automatically.</p></div>'}</div><p class="vgc-fine">Grouping does not change ownership, your profile showcase, gift visibility or sender disclosure. Removing a group preserves every gift.</p>`);restoreContext();}
 function open(){sync();pickerId=null;return load('','list','Your private gift organization.',listHTML);}
 function openInstance(id){sync();if(typeof id!=='string'||!id||id.length>255)return app.announce('Choose one of your owned gift instances.');pickerId=id;return load('?instance='+encode(id),'picker','Choose any number of private groups for this owned gift.',listHTML);}
 function pageHTML(data,kind){const p=data.page||{},offset=Number(p.offset)||0,total=Number(p.total)||0;return `<nav class="vgc-pages" aria-label="Owned gift pages"><button class="vh-secondary" data-vgc="page" data-kind="${kind}" data-offset="${Math.max(0,offset-50)}" ${offset?'':'disabled'}>Previous</button><span>${total?`${offset+1}–${Math.min(offset+(data.instances||[]).length,total)} of ${total}`:'0 gifts'}</span><button class="vh-secondary" data-vgc="page" data-kind="${kind}" data-offset="${offset+50}" ${p.hasMore?'':'disabled'}>Next</button></nav>`;}
 function itemHTML(item,group,inventory){return `<article class="vgc-item"><button type="button" class="vgc-art" data-vgc="inspect" data-design="${esc(item.catalogId)}" data-instance="${esc(item.id)}" aria-label="Inspect ${esc(title(item.catalogId))}">${art(item.catalogId)}</button><h3>${esc(title(item.catalogId))}</h3><small>${edition(item.catalogId)?esc(edition(item.catalogId))+' · ':''}Instance …${esc(item.id.slice(-8))}${item.pendingTransfer?' · Transfer pending':''}</small><button type="button" class="${item.included?'vh-secondary':'vh-primary'}" data-vgc="toggle" data-group="${esc(group.id)}" data-instance="${esc(item.id)}" data-revision="${Number(group.revision)}" data-included="${item.included?'false':'true'}" aria-pressed="${item.included}">${item.included?'Remove from group':'Add to group'}</button></article>`;}
 function groupHTML(data,inventory){const group=data.collection;context={kind:inventory?'inventory':'group',group,offset:Number(data.page?.offset)||0};pickerId=null;show(group.name,inventory?'Choose gifts you currently own. The same item may belong to multiple groups.':'These gifts are grouped privately. Ownership and showcase are separate.',`<div class="vgc-toolbar"><button class="vh-secondary" data-vgc="list">All collections</button><div class="vgc-actions"><button class="vh-secondary" data-vgc="${inventory?'group':'inventory'}" data-group="${esc(group.id)}">${inventory?'View collection':'Add gifts'}</button><button class="vh-text-button" data-vgc="rename" data-group="${esc(group.id)}" data-name="${esc(group.name)}" data-revision="${Number(group.revision)}">Rename</button></div></div>${errors}${data.instances.length?`<div class="vgc-grid">${data.instances.map(item=>itemHTML(item,group,inventory)).join('')}</div>`:`<div class="vgc-empty"><h3>${inventory?'No owned gifts yet':'This collection is empty'}</h3><p>${inventory?'Collect or receive a gift first. Browsing never changes your ownership.':'Add existing gifts from your inventory. Removing a group will never delete its gifts.'}</p>${inventory?'':`<button class="vh-primary" data-vgc="inventory" data-group="${esc(group.id)}">Add gifts</button>`}</div>`}${pageHTML(data,inventory?'inventory':'group')}<p class="vgc-fine">Private organization only. Opening a collection does not publish it to your profile.</p>`);restoreContext();}
 function openGroup(id,offset=0,inventory=false){if(!id)return open();return load(inventory?'/inventory?collection='+encode(id)+'&offset='+offset:'/'+encode(id)+'?offset='+offset,inventory?'inventory':'group','Loading currently owned gifts.',data=>groupHTML(data,inventory));}
 function createForm(){sync();const currentPicker=pickerId;context={...context,kind:'create'};show('Create gift collection','Choose a private name. This creates a group; it does not claim or move gifts.',`<form data-vgc-form="create" data-client="${crypto.randomUUID()}"><label class="vh-field">Collection name<input name="name" maxlength="40" required autocomplete="off" placeholder="Afterhours favorites"></label>${errors}<div class="vgc-actions"><button class="vh-primary" type="submit">Create collection</button><button class="vh-secondary" type="button" data-vgc="${currentPicker?'picker':'list'}">Cancel</button></div></form>`);}
 function renameForm(button){const id=button.dataset.group,name=button.dataset.name,revision=Number(button.dataset.revision);context={kind:'rename',group:{id,name,revision},offset:0};show('Rename collection','Only this private group name changes.',`<form data-vgc-form="rename" data-group="${esc(id)}" data-revision="${revision}"><label class="vh-field">Collection name<input name="name" maxlength="40" required autocomplete="off" value="${esc(name)}"></label>${errors}<div class="vgc-actions"><button class="vh-primary" type="submit">Save name</button><button type="button" class="vh-secondary" data-vgc="list">Cancel</button></div></form>`);}
 function deleteForm(button){const id=button.dataset.group,name=button.dataset.name,revision=Number(button.dataset.revision);context={kind:'delete',group:{id,name,revision},offset:0};show('Remove collection?',name,`<p>This removes only the group. Every gift remains owned, and other collections and your showcase stay as they are.</p><form data-vgc-form="delete" data-group="${esc(id)}" data-revision="${revision}">${errors}<div class="vgc-actions"><button class="vh-danger" type="submit">Remove group, keep gifts</button><button type="button" class="vh-secondary" data-vgc="list">Keep collection</button></div></form>`);}
 async function mutate(path,body,after){
  const current=guard();if(mutation||!identity)return;const token={id:crypto.randomUUID()},ticket=state().dialogGeneration;mutation=token;const controls=[...document.querySelectorAll?.('.vgc-panel button,.vgc-panel input')||[]],disabled=controls.map(node=>node.disabled);controls.forEach(node=>node.disabled=true);
  try{const data=await app.request('/api/gift-collections'+path,body);if(!current()||ticket!==state().dialogGeneration)return;await after(data);}
  catch(error){if(current()&&ticket===state().dialogGeneration)statusError(error);}
  finally{if(mutation===token){mutation=null;controls.forEach((node,index)=>{if(node.isConnected)node.disabled=disabled[index];});}}
 }
 async function submit(form){if(!form?.isConnected)return;const values=new FormData(form),kind=form.dataset.vgcForm;if(kind==='create'){const selected=pickerId;return mutate('',{name:String(values.get('name')||''),clientId:form.dataset.client},()=>selected?openInstance(selected):open());}if(kind==='rename')return mutate('/'+encode(form.dataset.group)+'/rename',{name:String(values.get('name')||''),expectedRevision:Number(form.dataset.revision)},()=>openGroup(form.dataset.group));if(kind==='delete')return mutate('/'+encode(form.dataset.group)+'/delete',{expectedRevision:Number(form.dataset.revision)},()=>open());}
 function reload(){if(context.kind==='picker'&&pickerId)return openInstance(pickerId);if(context.group?.id)return openGroup(context.group.id,context.offset,context.kind==='inventory');return open();}
 function action(button){const name=button.dataset.vgc;if(name==='list')return open();if(name==='picker'&&pickerId)return openInstance(pickerId);if(name==='group')return openGroup(button.dataset.group);if(name==='inventory')return openGroup(button.dataset.group,0,true);if(name==='create')return createForm();if(name==='rename')return renameForm(button);if(name==='delete')return deleteForm(button);if(name==='reload')return reload();if(name==='page')return openGroup(context.group?.id,Number(button.dataset.offset)||0,button.dataset.kind==='inventory');if(name==='inspect'){const current=guard(),snapshot={...context},selected=pickerId;return window.VoidCosmetics?.openItem?.(button.dataset.design,{instanceId:button.dataset.instance,returnLabel:'Back to private collection',returnTo:()=>{if(!current())return;focusInstance=button.dataset.instance||'';if(snapshot.kind==='picker'&&selected)return openInstance(selected);if(snapshot.group?.id)return openGroup(snapshot.group.id,snapshot.offset,snapshot.kind==='inventory');return open();}});}if(name==='toggle'){const groupId=button.dataset.group,instanceId=button.dataset.instance,included=button.dataset.included==='true',mode={...context},selected=pickerId;return mutate('/'+encode(groupId)+'/items',{instanceId,included,expectedRevision:Number(button.dataset.revision)},()=>mode.kind==='picker'&&selected?openInstance(selected):openGroup(groupId,mode.offset,mode.kind==='inventory'));}}
 function init(bridge){if(app)return;app=bridge;sync();document.addEventListener('click',event=>{const button=event.target.closest?.('[data-vgc]');if(!button||!state().account)return;event.preventDefault();Promise.resolve(action(button)).catch(statusError);});document.addEventListener('submit',event=>{if(!event.target?.dataset?.vgcForm||!state().account)return;event.preventDefault();submit(event.target).catch(statusError);});}
 const extension={id:'gift-collections',init,onAccount:sync,onLock:reset,handles:name=>name==='gift-collections',handleAction(name){if(name!=='gift-collections')return false;open();return true;}};
 window.VoidGiftCollections=Object.freeze({open,openInstance,openGroup,extension});
 function register(){window.VoidHome?.registerExtension?.(extension);}window.addEventListener('voidline:home-ready',register,{once:true});register();
})();
